/* Turia Yoga. Tokens: forest ink on cool paper, one brick accent. Radius: 14px surfaces, pill buttons, 10px inputs. */
:root {
  --bg: #f1f1ea;
  --surface: #e4e6dc;
  --surface-strong: #d6dacd;
  --ink: #1e2622;
  --muted: #56635a;
  --line: #c6cbbd;
  --accent: #a8402a;
  --accent-ink: #f7f6f0;
  --accent-hover: #8f3522;
  --error: #a3261b;
  --shadow: 0 18px 40px -24px rgb(30 38 34 / .35);

  --font-display: "Avenir Next", Avenir, Montserrat, Corbel, "URW Gothic", "DejaVu Sans", sans-serif;
  --font-body: Seravek, "Gill Sans Nova", Ubuntu, Calibri, "DejaVu Sans", sans-serif;

  --radius: 14px;
  --radius-input: 10px;
  --wrap: 1180px;
  --ease: cubic-bezier(.16, 1, .3, 1);
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #141a17;
    --surface: #1d2520;
    --surface-strong: #27312b;
    --ink: #e7e8e0;
    --muted: #a3aea5;
    --line: #34403a;
    --accent: #e9845f;
    --accent-ink: #141a17;
    --accent-hover: #f09a79;
    --error: #ff8f80;
    --shadow: 0 18px 40px -24px rgb(0 0 0 / .6);
  }
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 1.0625rem;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
}
img { display: block; max-width: 100%; height: auto; }
a { color: inherit; }
h1, h2, h3 { font-family: var(--font-display); font-weight: 600; letter-spacing: -.02em; margin: 0; }
h2 { font-size: clamp(1.9rem, 3.4vw, 2.75rem); line-height: 1.1; }
p { margin: 0; }

.wrap { width: min(100% - 2.5rem, var(--wrap)); margin-inline: auto; }
.lead { color: var(--muted); max-width: 52ch; margin-top: .75rem; font-size: 1.125rem; }

.skip {
  position: absolute; left: 1rem; top: -4rem;
  background: var(--ink); color: var(--bg); padding: .6rem 1rem; border-radius: 999px; z-index: 30;
}
.skip:focus { top: 1rem; }

:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 48px; padding: .75rem 1.5rem;
  border-radius: 999px; border: 1.5px solid transparent;
  font: 600 1rem/1 var(--font-body); text-decoration: none; white-space: nowrap; cursor: pointer;
  transition: background-color .25s var(--ease), border-color .25s var(--ease), transform .2s var(--ease);
}
.btn:active { transform: translateY(1px) scale(.98); }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: var(--accent-hover); }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--muted); }
.btn-ghost:hover { border-color: var(--ink); background: var(--surface); }
.btn-small { min-height: 42px; padding: .55rem 1.1rem; font-size: .95rem; }
.btn-block { width: 100%; }

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 20;
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.nav { display: flex; align-items: center; gap: 2rem; height: 68px; }
.brand { display: inline-flex; align-items: center; gap: .6rem; font: 600 1.15rem/1 var(--font-display); text-decoration: none; letter-spacing: -.01em; }
.brand-mark {
  width: 22px; height: 22px; border-radius: 50%;
  background: linear-gradient(180deg, var(--accent) 0 50%, var(--ink) 50% 100%);
}
.nav-links { display: flex; gap: 1.75rem; list-style: none; margin: 0 0 0 auto; padding: 0; }
.nav-links a { text-decoration: none; color: var(--muted); font-weight: 500; padding: .5rem 0; }
.nav-links a:hover { color: var(--ink); }

/* Hero */
.hero {
  display: grid; grid-template-columns: 1.1fr .9fr; gap: clamp(2rem, 5vw, 4.5rem);
  align-items: center; padding-block: clamp(2.5rem, 6vw, 5rem);
  min-height: calc(100dvh - 68px);
}
.hero-tag { color: var(--accent); font-weight: 600; margin-bottom: 1.1rem; }
.hero h1 { font-size: clamp(2.4rem, 4.6vw, 3.9rem); line-height: 1.05; max-width: 15ch; }
.hero-sub { margin-top: 1.4rem; font-size: 1.2rem; color: var(--muted); max-width: 40ch; }
.hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 2.1rem; }
.hero-media { margin: 0; }
.hero-media img {
  width: 100%; aspect-ratio: 5 / 6; object-fit: cover;
  border-radius: 999px 999px var(--radius) var(--radius);
  box-shadow: var(--shadow);
}

/* Classes */
.classes { background: var(--surface); padding-block: clamp(4rem, 8vw, 6.5rem); }
.classes-grid { display: grid; grid-template-columns: .8fr 1.2fr; gap: clamp(2rem, 5vw, 5rem); align-items: start; }
.classes-media { margin: 0; position: sticky; top: 96px; }
.classes-media img { width: 100%; aspect-ratio: 9 / 11; object-fit: cover; border-radius: var(--radius); }
.class-list { margin: 2.5rem 0 0; display: grid; grid-template-columns: 1fr 1fr; gap: 2.25rem 2.5rem; }
.class-item dt { font: 600 1.4rem/1.2 var(--font-display); letter-spacing: -.01em; padding-top: 1rem; border-top: 2px solid var(--accent); }
.class-item dd { margin: .6rem 0 0; }
.class-item .meta { margin-top: .6rem; color: var(--muted); font-size: .95rem; }

/* Schedule */
.schedule { padding-block: clamp(4rem, 8vw, 6.5rem); }
.tabs { display: flex; gap: .5rem; margin-top: 2rem; overflow-x: auto; padding-bottom: .25rem; }
.tabs[hidden] { display: none; }
.tabs button {
  min-width: 64px; min-height: 44px; padding: .5rem 1.1rem;
  border-radius: 999px; border: 1.5px solid var(--line); background: transparent; color: var(--ink);
  font: 600 1rem/1 var(--font-body); cursor: pointer;
  transition: background-color .2s var(--ease), border-color .2s var(--ease);
}
.tabs button:hover { border-color: var(--muted); }
.tabs button[aria-selected="true"] { background: var(--ink); color: var(--bg); border-color: var(--ink); }

.days { margin-top: 1.75rem; display: grid; gap: 1.5rem; }
.js .days { display: block; }
.day-name { font-size: 1.15rem; margin-bottom: .5rem; }
.js .day-name { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.js .day[hidden] { display: none; }
.sessions { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1rem; }
.sessions li {
  display: grid; grid-template-columns: auto 1fr; grid-template-rows: auto auto; column-gap: 1rem;
  padding: 1.25rem 1.35rem; border-radius: var(--radius); background: var(--surface);
}
.sessions .time { grid-row: span 2; font: 600 1.6rem/1 var(--font-display); font-variant-numeric: tabular-nums; align-self: center; }
.sessions .sname { font-weight: 600; }
.sessions .who { color: var(--muted); font-size: .95rem; }

/* Pricing */
.pricing { background: var(--surface); padding-block: clamp(4rem, 8vw, 6.5rem); }
.price-list { list-style: none; margin: 2.5rem 0 0; padding: 0; display: grid; gap: .75rem; max-width: 860px; }
.price-row {
  display: flex; align-items: center; justify-content: space-between; gap: 1.5rem;
  padding: 1.35rem 1.6rem; border-radius: var(--radius); background: var(--bg);
}
.price-row h3 { font-size: 1.25rem; }
.price-row .price-name p { color: var(--muted); margin-top: .2rem; }
.price { font: 600 1.25rem/1 var(--font-display); white-space: nowrap; }
.price .amount { font-size: 2.3rem; letter-spacing: -.03em; }
.price-row-featured { background: var(--ink); color: var(--bg); padding-block: 1.75rem; }
.price-row-featured .price-name p { color: color-mix(in srgb, var(--bg) 78%, var(--ink)); }
.price-note { margin-top: 1.5rem; color: var(--muted); max-width: 60ch; }

/* Booking */
.booking { display: grid; grid-template-columns: .85fr 1.15fr; gap: clamp(2rem, 5vw, 5rem); padding-block: clamp(4rem, 8vw, 6.5rem); align-items: start; }
.tips { margin: 2rem 0 0; padding: 0; list-style: none; display: grid; gap: .9rem; }
.tips li { padding-left: 1.4rem; position: relative; max-width: 42ch; }
.tips li::before { content: ""; position: absolute; left: 0; top: .7em; width: .6rem; height: 2px; background: var(--accent); }
.booking-panel { background: var(--surface); border-radius: var(--radius); padding: clamp(1.5rem, 3vw, 2.5rem); }

.form { display: grid; gap: 1.25rem; }
.field { display: grid; gap: .4rem; align-content: start; }
.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; }
.field label { font-weight: 600; }
.optional { font-weight: 400; color: var(--muted); }
.field input, .field select, .field textarea {
  width: 100%; min-height: 48px; padding: .7rem .9rem;
  font: 400 1rem/1.4 var(--font-body); color: var(--ink);
  background: var(--bg); border: 1.5px solid var(--muted); border-radius: var(--radius-input);
  transition: border-color .2s var(--ease);
}
.field textarea { resize: vertical; min-height: 96px; }
.field input:focus-visible, .field select:focus-visible, .field textarea:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; border-color: var(--ink); }
.field [aria-invalid="true"] { border-color: var(--error); }
.help { color: var(--muted); font-size: .9rem; }
.error { color: var(--error); font-size: .925rem; font-weight: 600; }
.field-check { grid-template-columns: auto 1fr; column-gap: .75rem; align-items: start; }
.field-check input { width: 22px; height: 22px; min-height: 0; margin: .15rem 0 0; accent-color: var(--accent); }
.field-check label { font-weight: 400; }
.field-check .error { grid-column: 1 / -1; }

.success { display: grid; gap: 1rem; }
.success[hidden] { display: none; }
.success h3 { font-size: 1.6rem; }
.success .btn { justify-self: start; margin-top: .5rem; }
.success:focus { outline: none; }

/* Footer */
.site-footer { border-top: 1px solid var(--line); padding-block: 3rem 2rem; }
.footer-grid { display: grid; grid-template-columns: 1fr 1fr auto; gap: 2rem; align-items: start; }
.footer-grid p + p { margin-top: .75rem; }
.footer-brand { margin-bottom: .9rem; }
.site-footer a { text-underline-offset: 3px; }
.legal { margin-top: 2.5rem; color: var(--muted); font-size: .9rem; }

/* Motion: entry and scroll reveal only when the visitor accepts motion */
@media (prefers-reduced-motion: no-preference) {
  .hero-copy > * { animation: rise .8s var(--ease) both; }
  .hero-copy > :nth-child(2) { animation-delay: .08s; }
  .hero-copy > :nth-child(3) { animation-delay: .16s; }
  .hero-copy > :nth-child(4) { animation-delay: .24s; }
  .hero-media { animation: fade 1.1s var(--ease) .1s both; }
  .js .reveal { opacity: 0; transform: translateY(18px); transition: opacity .7s var(--ease), transform .7s var(--ease); }
  .js .reveal.is-in { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: .01ms !important; animation: none !important; }
}
@keyframes rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

/* Tablet */
@media (max-width: 1023px) {
  .class-list { grid-template-columns: 1fr; }
}

/* Mobile: every multi-column layout collapses to one column */
@media (max-width: 767px) {
  .nav { gap: 1rem; height: 60px; }
  .nav-links { display: none; }
  .nav .btn-small { margin-left: auto; font-size: .9rem; padding-inline: 1rem; }
  .hero { grid-template-columns: 1fr; min-height: 0; padding-top: 2rem; }
  .hero-media { order: -1; }
  .hero-media img { aspect-ratio: 4 / 3; border-radius: var(--radius); }
  .classes-grid, .booking, .footer-grid, .field-row { grid-template-columns: 1fr; }
  .classes-media { position: static; }
  .classes-media img { aspect-ratio: 4 / 3; }
  .price-row { padding: 1.15rem 1.2rem; }
  .price .amount { font-size: 1.9rem; }
  .hero-actions .btn { flex: 1 1 auto; }
}
@media (max-width: 400px) {
  .brand span:last-child { display: none; }
}

content.content:
1	/* Turia Yoga. Tokens: forest ink on cool paper, one brick accent. Radius: 14px surfaces, pill buttons, 10px inputs. */
2	:root {
3	  --bg: #f1f1ea;
4	  --surface: #e4e6dc;
5	  --surface-strong: #d6dacd;
6	  --ink: #1e2622;
7	  --muted: #56635a;
8	  --line: #c6cbbd;
9	  --accent: #a8402a;
10	  --accent-ink: #f7f6f0;
11	  --accent-hover: #8f3522;
12	  --error: #a3261b;
13	  --shadow: 0 18px 40px -24px rgb(30 38 34 / .35);
14	
15	  --font-display: "Avenir Next", Avenir, Montserrat, Corbel, "URW Gothic", "DejaVu Sans", sans-serif;
16	  --font-body: Seravek, "Gill Sans Nova", Ubuntu, Calibri, "DejaVu Sans", sans-serif;
17	
18	  --radius: 14px;
19	  --radius-input: 10px;
20	  --wrap: 1180px;
21	  --ease: cubic-bezier(.16, 1, .3, 1);
22	  color-scheme: light dark;
23	}
24	
25	@media (prefers-color-scheme: dark) {
26	  :root {
27	    --bg: #141a17;
28	    --surface: #1d2520;
29	    --surface-strong: #27312b;
30	    --ink: #e7e8e0;
31	    --muted: #a3aea5;
32	    --line: #34403a;
33	    --accent: #e9845f;
34	    --accent-ink: #141a17;
35	    --accent-hover: #f09a79;
36	    --error: #ff8f80;
37	    --shadow: 0 18px 40px -24px rgb(0 0 0 / .6);
38	  }
39	}
40	
41	*, *::before, *::after { box-sizing: border-box; }
42	html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
43	body {
44	  margin: 0;
45	  background: var(--bg);
46	  color: var(--ink);
47	  font-family: var(--font-body);
48	  font-size: 1.0625rem;
49	  line-height: 1.6;
50	  text-rendering: optimizeLegibility;
51	}
52	img { display: block; max-width: 100%; height: auto; }
53	a { color: inherit; }
54	h1, h2, h3 { font-family: var(--font-display); font-weight: 600; letter-spacing: -.02em; margin: 0; }
55	h2 { font-size: clamp(1.9rem, 3.4vw, 2.75rem); line-height: 1.1; }
56	p { margin: 0; }
57	
58	.wrap { width: min(100% - 2.5rem, var(--wrap)); margin-inline: auto; }
59	.lead { color: var(--muted); max-width: 52ch; margin-top: .75rem; font-size: 1.125rem; }
60	
61	.skip {
62	  position: absolute; left: 1rem; top: -4rem;
63	  background: var(--ink); color: var(--bg); padding: .6rem 1rem; border-radius: 999px; z-index: 30;
64	}
65	.skip:focus { top: 1rem; }
66	
67	:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }
68	
69	/* Buttons */
70	.btn {
71	  display: inline-flex; align-items: center; justify-content: center;
72	  min-height: 48px; padding: .75rem 1.5rem;
73	  border-radius: 999px; border: 1.5px solid transparent;
74	  font: 600 1rem/1 var(--font-body); text-decoration: none; white-space: nowrap; cursor: pointer;
75	  transition: background-color .25s var(--ease), border-color .25s var(--ease), transform .2s var(--ease);
76	}
77	.btn:active { transform: translateY(1px) scale(.98); }
78	.btn-primary { background: var(--accent); color: var(--accent-ink); }
79	.btn-primary:hover { background: var(--accent-hover); }
80	.btn-ghost { background: transparent; color: var(--ink); border-color: var(--muted); }
81	.btn-ghost:hover { border-color: var(--ink); background: var(--surface); }
82	.btn-small { min-height: 42px; padding: .55rem 1.1rem; font-size: .95rem; }
83	.btn-block { width: 100%; }
84	
85	/* Header */
86	.site-header {
87	  position: sticky; top: 0; z-index: 20;
88	  background: color-mix(in srgb, var(--bg) 88%, transparent);
89	  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
90	  border-bottom: 1px solid var(--line);
91	}
92	.nav { display: flex; align-items: center; gap: 2rem; height: 68px; }
93	.brand { display: inline-flex; align-items: center; gap: .6rem; font: 600 1.15rem/1 var(--font-display); text-decoration: none; letter-spacing: -.01em; }
94	.brand-mark {
95	  width: 22px; height: 22px; border-radius: 50%;
96	  background: linear-gradient(180deg, var(--accent) 0 50%, var(--ink) 50% 100%);
97	}
98	.nav-links { display: flex; gap: 1.75rem; list-style: none; margin: 0 0 0 auto; padding: 0; }
99	.nav-links a { text-decoration: none; color: var(--muted); font-weight: 500; padding: .5rem 0; }
100	.nav-links a:hover { color: var(--ink); }
101	
102	/* Hero */
103	.hero {
104	  display: grid; grid-template-columns: 1.1fr .9fr; gap: clamp(2rem, 5vw, 4.5rem);
105	  align-items: center; padding-block: clamp(2.5rem, 6vw, 5rem);
106	  min-height: calc(100dvh - 68px);
107	}
108	.hero-tag { color: var(--accent); font-weight: 600; margin-bottom: 1.1rem; }
109	.hero h1 { font-size: clamp(2.4rem, 4.6vw, 3.9rem); line-height: 1.05; max-width: 15ch; }
110	.hero-sub { margin-top: 1.4rem; font-size: 1.2rem; color: var(--muted); max-width: 40ch; }
111	.hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 2.1rem; }
112	.hero-media { margin: 0; }
113	.hero-media img {
114	  width: 100%; aspect-ratio: 5 / 6; object-fit: cover;
115	  border-radius: 999px 999px var(--radius) var(--radius);
116	  box-shadow: var(--shadow);
117	}
118	
119	/* Classes */
120	.classes { background: var(--surface); padding-block: clamp(4rem, 8vw, 6.5rem); }
121	.classes-grid { display: grid; grid-template-columns: .8fr 1.2fr; gap: clamp(2rem, 5vw, 5rem); align-items: start; }
122	.classes-media { margin: 0; position: sticky; top: 96px; }
123	.classes-media img { width: 100%; aspect-ratio: 9 / 11; object-fit: cover; border-radius: var(--radius); }
124	.class-list { margin: 2.5rem 0 0; display: grid; grid-template-columns: 1fr 1fr; gap: 2.25rem 2.5rem; }
125	.class-item dt { font: 600 1.4rem/1.2 var(--font-display); letter-spacing: -.01em; padding-top: 1rem; border-top: 2px solid var(--accent); }
126	.class-item dd { margin: .6rem 0 0; }
127	.class-item .meta { margin-top: .6rem; color: var(--muted); font-size: .95rem; }
128	
129	/* Schedule */
130	.schedule { padding-block: clamp(4rem, 8vw, 6.5rem); }
131	.tabs { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: 2rem; }
132	.tabs[hidden] { display: none; }
133	.tabs button {
134	  min-width: 64px; min-height: 44px; padding: .5rem 1.1rem;
135	  border-radius: 999px; border: 1.5px solid var(--line); background: transparent; color: var(--ink);
136	  font: 600 1rem/1 var(--font-body); cursor: pointer;
137	  transition: background-color .2s var(--ease), border-color .2s var(--ease);
138	}
139	.tabs button:hover { border-color: var(--muted); }
140	.tabs button[aria-selected="true"] { background: var(--ink); color: var(--bg); border-color: var(--ink); }
141	
142	.days { margin-top: 1.75rem; display: grid; gap: 1.5rem; }
143	.js .days { display: block; }
144	.day-name { font-size: 1.15rem; margin-bottom: .5rem; }
145	.js .day-name { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
146	.js .day[hidden] { display: none; }
147	.sessions { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1rem; }
148	.sessions li {
149	  display: grid; grid-template-columns: auto 1fr; grid-template-rows: auto auto; column-gap: 1rem;
150	  padding: 1.25rem 1.35rem; border-radius: var(--radius); background: var(--surface);
151	}
152	.sessions .time { grid-row: span 2; font: 600 1.6rem/1 var(--font-display); font-variant-numeric: tabular-nums; align-self: center; }
153	.sessions .sname { font-weight: 600; }
154	.sessions .who { color: var(--muted); font-size: .95rem; }
155	
156	/* Pricing */
157	.pricing { background: var(--surface); padding-block: clamp(4rem, 8vw, 6.5rem); }
158	.price-list { list-style: none; margin: 2.5rem 0 0; padding: 0; display: grid; gap: .75rem; max-width: 860px; }
159	.price-row {
160	  display: flex; align-items: center; justify-content: space-between; gap: 1.5rem;
161	  padding: 1.35rem 1.6rem; border-radius: var(--radius); background: var(--bg);
162	}
163	.price-row h3 { font-size: 1.25rem; }
164	.price-row .price-name p { color: var(--muted); margin-top: .2rem; }
165	.price { font: 600 1.25rem/1 var(--font-display); white-space: nowrap; }
166	.price .amount { font-size: 2.3rem; letter-spacing: -.03em; }
167	.price-row-featured { background: var(--ink); color: var(--bg); padding-block: 1.75rem; }
168	.price-row-featured .price-name p { color: color-mix(in srgb, var(--bg) 78%, var(--ink)); }
169	.price-note { margin-top: 1.5rem; color: var(--muted); max-width: 60ch; }
170	
171	/* Booking */
172	.booking { display: grid; grid-template-columns: .85fr 1.15fr; gap: clamp(2rem, 5vw, 5rem); padding-block: clamp(4rem, 8vw, 6.5rem); align-items: start; }
173	.tips { margin: 2rem 0 0; padding: 0; list-style: none; display: grid; gap: .9rem; }
174	.tips li { padding-left: 1.4rem; position: relative; max-width: 42ch; }
175	.tips li::before { content: ""; position: absolute; left: 0; top: .7em; width: .6rem; height: 2px; background: var(--accent); }
176	.booking-panel { background: var(--surface); border-radius: var(--radius); padding: clamp(1.5rem, 3vw, 2.5rem); }
177	
178	.form { display: grid; gap: 1.25rem; }
179	.form[hidden] { display: none; }
180	.field { display: grid; gap: .4rem; align-content: start; }
181	.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; }
182	.field label { font-weight: 600; }
183	.optional { font-weight: 400; color: var(--muted); }
184	.field input, .field select, .field textarea {
185	  width: 100%; min-height: 48px; padding: .7rem .9rem;
186	  font: 400 1rem/1.4 var(--font-body); color: var(--ink);
187	  background: var(--bg); border: 1.5px solid var(--muted); border-radius: var(--radius-input);
188	  transition: border-color .2s var(--ease);
189	}
190	.field textarea { resize: vertical; min-height: 96px; }
191	.field input:focus-visible, .field select:focus-visible, .field textarea:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; border-color: var(--ink); }
192	.field [aria-invalid="true"] { border-color: var(--error); }
193	.help { color: var(--muted); font-size: .9rem; }
194	.error { color: var(--error); font-size: .925rem; font-weight: 600; }
195	.field-check { grid-template-columns: auto 1fr; column-gap: .75rem; align-items: start; }
196	.field-check input { width: 22px; height: 22px; min-height: 0; margin: .15rem 0 0; accent-color: var(--accent); }
197	.field-check label { font-weight: 400; }
198	.field-check .error { grid-column: 1 / -1; }
199	
200	.success { display: grid; gap: 1rem; }
201	.success[hidden] { display: none; }
202	.success h3 { font-size: 1.6rem; }
203	.success .btn { justify-self: start; margin-top: .5rem; }
204	.success:focus { outline: none; }
205	
206	/* Footer */
207	.site-footer { border-top: 1px solid var(--line); padding-block: 3rem 2rem; }
208	.footer-grid { display: grid; grid-template-columns: 1fr 1fr auto; gap: 2rem; align-items: start; }
209	.footer-grid p + p { margin-top: .75rem; }
210	.footer-brand { margin-bottom: .9rem; }
211	.site-footer a { text-underline-offset: 3px; }
212	.legal { margin-top: 2.5rem; color: var(--muted); font-size: .9rem; }
213	
214	/* Motion: hero entry only when the visitor accepts motion */
215	@media (prefers-reduced-motion: no-preference) {
216	  .hero-copy > * { animation: rise .8s var(--ease) both; }
217	  .hero-copy > :nth-child(2) { animation-delay: .08s; }
218	  .hero-copy > :nth-child(3) { animation-delay: .16s; }
219	  .hero-copy > :nth-child(4) { animation-delay: .24s; }
220	  .hero-media { animation: fade 1.1s var(--ease) .1s both; }
221	}
222	@media (prefers-reduced-motion: reduce) {
223	  html { scroll-behavior: auto; }
224	  *, *::before, *::after { transition-duration: .01ms !important; animation: none !important; }
225	}
226	@keyframes rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
227	@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
228	
229	/* Tablet */
230	@media (max-width: 1023px) {
231	  .class-list { grid-template-columns: 1fr; }
232	}
233	
234	/* Mobile: every multi-column layout collapses to one column */
235	@media (max-width: 767px) {
236	  .nav { gap: 1rem; height: 60px; }
237	  .nav-links { display: none; }
238	  .nav .btn-small { margin-left: auto; font-size: .9rem; padding-inline: 1rem; }
239	  .hero { grid-template-columns: 1fr; min-height: 0; padding-top: 2rem; }
240	  .hero-media { order: -1; }
241	  .hero-media img { aspect-ratio: 4 / 3; border-radius: var(--radius); }
242	  .classes-grid, .booking, .footer-grid, .field-row { grid-template-columns: 1fr; }
243	  .classes-media { position: static; }
244	  .classes-media img { aspect-ratio: 4 / 3; }
245	  .price-row { padding: 1.15rem 1.2rem; }
246	  .price .amount { font-size: 1.9rem; }
247	  .hero-actions .btn { flex: 1 1 auto; }
248	}
249	@media (max-width: 359px) {
250	  .nav .brand span:last-child { display: none; }
251	}
