175	.tips li::before { content: ""; position: absolute; left: 0; top: .7em; width: .6rem; height: 2px; background: var(--accent); }
176	.booking-panel { background: var(--surface); border-radius: var(--radius); padding: clamp(1.5rem, 3vw, 2.5rem); }
177	
178	.form { display: grid; gap: 1.25rem; }
179	.form[hidden] { display: none; }
180	.field { display: grid; gap: .4rem; align-content: start; }
181	.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; }
182	.field label { font-weight: 600; }
183	.optional { font-weight: 400; color: var(--muted); }
184	.field input, .field select, .field textarea {
185	  width: 100%; min-height: 48px; padding: .7rem .9rem;
186	  font: 400 1rem/1.4 var(--font-body); color: var(--ink);
187	  background: var(--bg); border: 1.5px solid var(--muted); border-radius: var(--radius-input);
188	  transition: border-color .2s var(--ease);
189	}
190	.field textarea { resize: vertical; min-height: 96px; }
191	.field input:focus-visible, .field select:focus-visible, .field textarea:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; border-color: var(--ink); }
192	.field [aria-invalid="true"] { border-color: var(--error); }
193	.help { color: var(--muted); font-size: .9rem; }
194	.error { color: var(--error); font-size: .925rem; font-weight: 600; }
195	.field-check { grid-template-columns: auto 1fr; column-gap: .75rem; align-items: start; }
196	.field-check input { width: 24px; height: 24px; min-height: 0; margin: .1rem 0 0; accent-color: var(--accent); }
197	.field-check label { padding-block: .1rem; }
198	.field-check label a { text-underline-offset: 2px; }
199	.form-privacy { margin-top: -.25rem; }
200	.field-check label { font-weight: 400; }
201	.field-check .error { grid-column: 1 / -1; }
202	
203	.success { display: grid; gap: 1rem; }
204	.success[hidden] { display: none; }
205	.success h3 { font-size: 1.6rem; }
206	.success .btn { justify-self: start; margin-top: .5rem; }
207	.success:focus { outline: none; }
208	
209	/* Footer */
210	.site-footer { border-top: 1px solid var(--line); padding-block: 3rem 2rem; }
211	.footer-grid { display: grid; grid-template-columns: 1fr 1fr auto; gap: 2rem; align-items: start; }
212	.footer-grid p + p { margin-top: .75rem; }
213	.footer-brand { margin-bottom: .9rem; }
214	.site-footer a { text-underline-offset: 3px; }
215	.legal { margin-top: 1rem; color: var(--muted); font-size: .9rem; }
216	.legal-links { display: flex; flex-wrap: wrap; gap: .25rem 1.5rem; margin-top: 2.5rem; font-size: .95rem; }
217	.legal-links a { color: var(--muted); padding-block: .6rem; text-underline-offset: 3px; }
218	.legal-links a:hover, .legal-links a[aria-current="page"] { color: var(--ink); }
219	
220	/* Legal pages */
221	.nav-back { margin-left: auto; }
222	.legal-page { max-width: 760px; padding-block: clamp(3rem, 6vw, 5rem); }
223	.legal-page h1 { font-size: clamp(2.1rem, 4vw, 3rem); line-height: 1.1; }
224	.legal-page .updated { color: var(--muted); margin-top: .75rem; }
225	.legal-page h2 { font-size: 1.35rem; margin-top: 2.5rem; }
226	.legal-page p, .legal-page ul { margin-top: .75rem; max-width: 65ch; }
227	.legal-data { padding-left: 1.2rem; }
228	.legal-page a { text-underline-offset: 3px; }
229	
230	/* Motion: hero entry only when the visitor accepts motion */
231	@media (prefers-reduced-motion: no-preference) {
232	  .hero-copy > * { animation: rise .8s var(--ease) both; }
233	  .hero-copy > :nth-child(2) { animation-delay: .08s; }
234	  .hero-copy > :nth-child(3) { animation-delay: .16s; }
235	  .hero-copy > :nth-child(4) { animation-delay: .24s; }
236	  .hero-media { animation: fade 1.1s var(--ease) .1s both; }
237	}
238	@media (prefers-reduced-motion: reduce) {
239	  html { scroll-behavior: auto; }
240	  *, *::before, *::after { transition-duration: .01ms !important; animation: none !important; }
241	}
242	@keyframes rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
243	@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
244	
245	/* Tablet */
246	@media (max-width: 1023px) {
247	  .class-list { grid-template-columns: 1fr; }
248	}
