250	/* Mobile: every multi-column layout collapses to one column */
251	@media (max-width: 767px) {
252	  .nav { gap: 1rem; height: 60px; }
253	  .nav-links { display: none; }
254	  .nav .btn-small { margin-left: auto; font-size: .9rem; padding-inline: 1rem; }
255	  .hero { grid-template-columns: 1fr; min-height: 0; padding-top: 2rem; }
256	  .hero-media { order: -1; }
257	  .hero-media img { aspect-ratio: 4 / 3; border-radius: var(--radius); }
258	  .classes-grid, .booking, .footer-grid, .field-row { grid-template-columns: 1fr; }
