1	// Turia Yoga: schedule tabs and the free-class booking form.
2	// The weekly schedule in index.html is the single source of truth; the form reads it from the DOM.
3	(function () {
4	  "use strict";
5	  document.documentElement.classList.add("js");
6	
7	  document.addEventListener("DOMContentLoaded", function () {
8	    initTabs();
9	    initBooking();
10	  });
11	
12	  function initTabs() {
13	    var tablist = document.querySelector(".tabs");
14	    if (!tablist) return;
15	    var tabs = Array.prototype.slice.call(tablist.querySelectorAll("[role=tab]"));
16	    var panels = Array.prototype.slice.call(document.querySelectorAll(".day"));
17	    tablist.hidden = false;
18	
19	    function select(tab, focus) {
20	      tabs.forEach(function (t) {
21	        var on = t === tab;
22	        t.setAttribute("aria-selected", on ? "true" : "false");
23	        t.tabIndex = on ? 0 : -1;
24	      });
25	      panels.forEach(function (p) { p.hidden = p.id !== tab.getAttribute("aria-controls"); });
26	      if (focus) tab.focus();
27	    }
28	
29	    tabs.forEach(function (tab, i) {
30	      tab.addEventListener("click", function () { select(tab, false); });
31	      tab.addEventListener("keydown", function (e) {
32	        var next = null;
33	        if (e.key === "ArrowRight") next = tabs[(i + 1) % tabs.length];
34	        else if (e.key === "ArrowLeft") next = tabs[(i - 1 + tabs.length) % tabs.length];
35	        else if (e.key === "Home") next = tabs[0];
36	        else if (e.key === "End") next = tabs[tabs.length - 1];
37	        if (next) { e.preventDefault(); select(next, true); }
38	      });
39	    });
40	
41	    // Open on today's day (Sunday falls back to Monday, the studio is closed).
42	    var today = new Date().getDay();
43	    select(tabs[today >= 1 && today <= 6 ? today - 1 : 0], false);
44	  }
45	
46	
47	  function sessionsByDay() {
48	    var map = {};
49	    document.querySelectorAll(".day").forEach(function (day) {
50	      var list = [];
51	      day.querySelectorAll("li[data-time]").forEach(function (li) {
52	        list.push({ time: li.getAttribute("data-time"), name: li.getAttribute("data-class") });
53	      });
54	      map[day.getAttribute("data-day")] = { name: day.getAttribute("data-name"), sessions: list };
55	    });
56	    return map;
57	  }
58	
59	  function isoDate(d) {
60	    var m = String(d.getMonth() + 1).padStart(2, "0");
61	    var day = String(d.getDate()).padStart(2, "0");
62	    return d.getFullYear() + "-" + m + "-" + day;
63	  }
64	
65	  function parseDate(value) {
66	    var parts = value.split("-").map(Number);
67	    if (parts.length !== 3 || parts.some(isNaN)) return null;
68	    return new Date(parts[0], parts[1] - 1, parts[2]);
69	  }
70	
71	  function initBooking() {
72	    var form = document.getElementById("booking-form");
73	    if (!form) return;
74	    var success = document.getElementById("booking-success");
75	    var summary = document.getElementById("success-summary");
76	    var resetBtn = document.getElementById("booking-reset");
77	    var fecha = form.elements.fecha;
78	    var clase = form.elements.clase;
79	    var schedule = sessionsByDay();
80	
81	    var today = new Date();
82	    var max = new Date(today.getFullYear(), today.getMonth() + 2, today.getDate());
83	    fecha.min = isoDate(today);
84	    fecha.max = isoDate(max);
85	
86	    function setError(field, msg) {
87	      var err = document.getElementById(field.id + "-error");
88	      if (msg) {
89	        err.textContent = msg;
90	        err.hidden = false;
91	        field.setAttribute("aria-invalid", "true");
92	      } else {
93	        err.textContent = "";
94	        err.hidden = true;
95	        field.removeAttribute("aria-invalid");
96	      }
97	    }
98	
99	    function fillClasses() {
100	      clase.innerHTML = "";
101	      var d = fecha.value ? parseDate(fecha.value) : null;
102	      var day = d ? schedule[String(d.getDay())] : null;
103	      var placeholder = document.createElement("option");
104	      placeholder.value = "";
105	      if (!d) placeholder.textContent = "Elige primero el día";
106	      else if (!day) placeholder.textContent = "Ese día no hay clases";
107	      else placeholder.textContent = "Elige una clase";
108	      clase.appendChild(placeholder);
109	      if (!day) { clase.disabled = !!d; return; }
110	      clase.disabled = false;
111	      day.sessions.forEach(function (s) {
112	        var opt = document.createElement("option");
113	        opt.value = s.time + " " + s.name;
114	        opt.textContent = s.time + "  " + s.name;
115	        clase.appendChild(opt);
116	      });
117	    }
118	
119	    function checkFecha() {
120	      if (!fecha.value) return "Elige el día de tu clase.";
121	      var d = parseDate(fecha.value);
122	      if (!d) return "Escribe una fecha válida.";
123	      var start = parseDate(fecha.min);
124	      if (d < start) return "Elige un día a partir de hoy.";
125	      if (d > parseDate(fecha.max)) return "Por ahora reservamos con un máximo de dos meses de antelación.";
126	      if (d.getDay() === 0) return "Los domingos el estudio está cerrado. Elige otro día.";
127	      return "";
128	    }
129	
130	    var rules = {
131	      nombre: function (f) { return f.value.trim().length >= 2 ? "" : "Dinos tu nombre."; },
132	      email: function (f) {
133	        var v = f.value.trim();
134	        if (!v) return "Necesitamos tu correo para confirmarte la plaza.";
135	        return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v) ? "" : "Revisa el correo, parece que falta algo (ejemplo: nombre@correo.es).";
136	      },
137	      telefono: function (f) {
138	        var v = f.value.replace(/[\s().-]/g, "");
139	        if (!v) return "";
140	        return /^\+?\d{9,13}$/.test(v) ? "" : "Revisa el teléfono: deben ser al menos 9 cifras.";
141	      },
142	      fecha: function () { return checkFecha(); },
143	      clase: function (f) { return f.value ? "" : "Elige la clase a la que quieres venir."; },
144	      privacidad: function (f) { return f.checked ? "" : "Necesitamos tu permiso para guardar la reserva."; }
145	    };
146	
147	    fecha.addEventListener("change", function () {
148	      fillClasses();
149	      setError(fecha, checkFecha());
150	      if (clase.getAttribute("aria-invalid")) setError(clase, "");
151	    });
152	
153	    Object.keys(rules).forEach(function (name) {
154	      var field = form.elements[name];
155	      field.addEventListener("blur", function () {
156	        if (field.getAttribute("aria-invalid") === "true") setError(field, rules[name](field));
157	      });
158	      field.addEventListener("input", function () {
159	        if (field.getAttribute("aria-invalid") === "true") setError(field, rules[name](field));
160	      });
161	    });
162	
163	    form.addEventListener("submit", function (e) {
164	      e.preventDefault();
165	      var firstBad = null;
166	      Object.keys(rules).forEach(function (name) {
167	        var field = form.elements[name];
168	        var msg = rules[name](field);
169	        setError(field, msg);
170	        if (msg && !firstBad) firstBad = field;
171	      });
172	      if (firstBad) { firstBad.focus(); return; }
173	
174	      var d = parseDate(fecha.value);
175	      var dayName = schedule[String(d.getDay())].name;
176	      var fechaTxt = dayName + " " + d.getDate() + "/" + (d.getMonth() + 1) + "/" + d.getFullYear();
177	      var nombre = form.elements.nombre.value.trim();
178	      var body = [
179	        "Hola, quiero reservar mi primera clase gratis.",
180	        "",
181	        "Nombre: " + nombre,
182	        "Correo: " + form.elements.email.value.trim(),
183	        "Teléfono: " + (form.elements.telefono.value.trim() || "no indicado"),
184	        "Día: " + fechaTxt,
185	        "Clase: " + clase.value,
186	        "Comentarios: " + (form.elements.mensaje.value.trim() || "ninguno")
187	      ].join("\n");
188	
189	      // Static site: the request travels as a pre-written email the visitor sends.
190	      window.location.href = "mailto:hola@turiayoga.es?subject=" +
191	        encodeURIComponent("Primera clase gratis: " + clase.value + ", " + fechaTxt) +
192	        "&body=" + encodeURIComponent(body);
193	
194	      summary.textContent = nombre + ", has elegido " + clase.value + " el " + fechaTxt + ".";
195	      form.hidden = true;
196	      success.hidden = false;
197	      success.focus();
198	    });
199	
200	    resetBtn.addEventListener("click", function () {
201	      form.reset();
202	      fillClasses();
203	      success.hidden = true;
204	      form.hidden = false;
205	      form.elements.nombre.focus();
206	    });
207	
208	    fillClasses();
209	  }
210	})();
